    import random
    rng = random.Random(7)
    readings = [rng.randint(0, 50) for _ in range(300)]
    best = 0
    for i in range(len(readings)):
        lo = hi = readings[i]
        for j in range(i, len(readings)):
            lo, hi = min(lo, readings[j]), max(hi, readings[j])
            if hi - lo > 10:
                break
            best = max(best, j - i + 1)
    assert longest_stable_window(readings, 10) == best

