from collections import deque


def longest_stable_window(readings: list[int], tolerance: int) -> int:
    maxq: deque[int] = deque()  # indices, readings decreasing
    minq: deque[int] = deque()  # indices, readings increasing
    left = best = 0
    for right, value in enumerate(readings):
        while maxq and readings[maxq[-1]] <= value:
            maxq.pop()
        maxq.append(right)
        while minq and readings[minq[-1]] >= value:
            minq.pop()
        minq.append(right)
        while readings[maxq[0]] - readings[minq[0]] > tolerance:
            left += 1
            if maxq[0] < left:
                maxq.popleft()
            if minq[0] < left:
                minq.popleft()
        best = max(best, right - left + 1)
    return best
